// Helper to safely get data from other nodes
function getNodeData(nodeName) {
    try {
        const data = $(nodeName).all();
        if (!data || !Array.isArray(data)) {
            return [];
        }
        return data;
    } catch (e) {
        throw new Error(`Failed to retrieve data from node '${nodeName}'. Please ensure that a node named '${nodeName}' exists in your workflow, is connected in series, and has executed successfully before this node.`);
    }
}

// Normalize helpers
function normalizeString(val) {
    if (val === null || val === undefined) {
        return "";
    }
    return String(val).trim().replace(/\s+/g, ' ').toLowerCase();
}

// Clean and normalize email addresses, extracting from brackets if present
function cleanEmail(rawVal) {
    if (!rawVal) {
        return "";
    }
    const valStr = String(rawVal).trim();
    const match = valStr.match(/<([^>]+)>/);
    if (match) {
        return match[1].trim().toLowerCase();
    }
    return valStr.toLowerCase();
}

// Date parsing for multiple standard formats
function parseDate(dateVal, defaultYear) {
    if (!dateVal) {
        return null;
    }
    if (dateVal instanceof Date) {
        return dateVal;
    }
    try {
        let valStr = String(dateVal).trim();
        if (valStr.includes(" ")) {
            valStr = valStr.split(" ")[0];
        }
        if (valStr.includes("T")) {
            valStr = valStr.split("T")[0];
        }

        let parsed = new Date(valStr);
        if (!isNaN(parsed.getTime())) {
            parsed.setHours(0, 0, 0, 0);
            if (parsed.getFullYear() === 2001 && defaultYear) {
                const parts = valStr.split(/[-/,\s]+/);
                let hasExplicit2001Year = false;
                if (parts.length >= 3) {
                    const first = parts[0];
                    const last = parts[parts.length - 1];
                    if (first === "2001" || first === "01" || last === "2001" || last === "01") {
                        hasExplicit2001Year = true;
                    }
                }
                if (!hasExplicit2001Year) {
                    parsed.setFullYear(defaultYear);
                }
            }
            return parsed;
        }

        const partsDash = valStr.split("-");
        if (partsDash.length === 3) {
            const months = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
            const mIdx = months.indexOf(partsDash[1].toLowerCase().substring(0, 3));
            if (mIdx !== -1) {
                let day = parseInt(partsDash[0], 10);
                let year = parseInt(partsDash[2], 10);
                if (year < 100) year += 2000;
                return new Date(year, mIdx, day, 0, 0, 0, 0);
            }
        }

        const partsSlash = valStr.split("/");
        if (partsSlash.length === 3) {
            let p0 = parseInt(partsSlash[0], 10);
            let p1 = parseInt(partsSlash[1], 10);
            let p2 = parseInt(partsSlash[2], 10);
            if (p2 < 100) p2 += 2000;
            if (p0 > 12) {
                return new Date(p2, p1 - 1, p0, 0, 0, 0, 0);
            } else {
                let d = new Date(p2, p0 - 1, p1, 0, 0, 0, 0);
                if (!isNaN(d.getTime())) return d;
            }
        }
    } catch (e) {}
    return null;
}

// Format Date object to YYYY-MM-DD
function formatDateStr(date) {
    if (!date) return null;
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
}

// Format Date object to YYYY-MM-DD HH:mm:ss
function formatDateTime(date) {
    if (!date) return "";
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    const hh = String(date.getHours()).padStart(2, '0');
    const mm = String(date.getMinutes()).padStart(2, '0');
    const ss = String(date.getSeconds()).padStart(2, '0');
    return `${y}-${m}-${d} ${hh}:${mm}:${ss}`;
}

// Mapping of header variants to support fuzzy column name checking in the Code Node
const HEADER_MAPPINGS = {
    'vendor_name': [
        'customer/vendor name', 'customer vendor name', 'vendor name', 
        'supplier name', 'customer/supplier name', 'supplier_name'
    ],
    'vendor_code': [
        'customer/vendor code', 'customer vendor code', 'vendor code', 
        'supplier code', 'customer/supplier code', 'supplier_code', 'vendor_code'
    ],
    'po_number': [
        'po', 'po number', 'po_number', 'po no', 'po_no'
    ],
    'po_date': [
        'po date', 'po_date', 'date'
    ],
    'shipto': [
        'ship-to Code', 'ship-to', 'shipto code', 'shipto', 'ship_to_code'
    ],
    'item_no': [
        'item no.', 'item no', 'item_no', 'item number', 'item_number'
    ],
    'description': [
        'descrption', 'description', 'desc', 'item description'
    ],
    'qty': [
        'po qty', 'po_qty', 'qty', 'quantity'
    ],
    'price': [
        'unit price', 'unit_price', 'price'
    ],
    'amount': [
        'amount', 'value'
    ],
    'terms': [
        'paymnet terms', 'payment terms', 'payment_terms', 'terms'
    ],
    'arrival_date': [
        'arrival date', 'arrival_date', 'arrival'
    ],
    'uom': [
        'unit of measure', 'unit_of_measure', 'uom'
    ]
};

// Retrieve values from row dictionary using fuzzy header variant matching
function getValueByHeaderVariant(row, targetKey, defaultVal = null) {
    if (!row) return defaultVal;

    // Check exact key match
    if (row.hasOwnProperty(targetKey)) {
        return row[targetKey];
    }

    // Normalize and check keys
    const variants = HEADER_MAPPINGS[targetKey] || [];
    const keys = Object.keys(row);

    for (const key of keys) {
        const normKey = normalizeString(key);
        if (normKey === targetKey) return row[key];

        for (const variant of variants) {
            if (normKey === variant) return row[key];

            // Collapse symbols to check
            const collapsedKey = normKey.replace(/[^a-z0-9]/g, '');
            const collapsedVariant = variant.replace(/[^a-z0-9]/g, '');
            if (collapsedKey === collapsedVariant) return row[key];
        }
    }

    return defaultVal;
}

// 1. Load config parameters
const config = $("Config").first().json;
const clientCode = config.clientCode;
const runDateStr = config.runDate;
const masterTitle = config.masterSheetName || 'Material and Supplier Master Data';
const runDate = parseDate(runDateStr) || new Date();
runDate.setHours(0, 0, 0, 0);

const runDatetime = new Date(runDate);
runDatetime.setHours(10, 0, 0, 0);

// 2. Fetch data from previous workflow nodes
const contactsRaw = getNodeData("Read Contacts");
const poLatestRaw = getNodeData("Read Open PO Latest");
const masterRaw = getNodeData("Read Supplier Master");
const pocRaw = getNodeData("Read PO Consolidated");
const logsRaw = getNodeData("Read Comm Logs");
const bandsRaw = getNodeData("Read Bands");

// 3. Map contacts
const contactsMap = {};
for (const item of contactsRaw) {
    const row = item.json;
    const vname = getValueByHeaderVariant(row, 'vendor_name');
    if (vname) {
        const normV = normalizeString(vname);
        contactsMap[normV] = {
            contact_name: row["Contact name"] || row["contact_name"] || "",
            email: cleanEmail(row["mail id"] || row["email"] || row["mail_id"] || ""),
            phone: row["Phone"] !== null && row["Phone"] !== undefined ? String(row["Phone"]).trim() : ""
        };
    }
}

// 4. Extract existing Master records
const existingMasterCombos = new Set();
const existingSupplierCodes = {};
const existingSupplierCodesByCode = {};
const existingSNums = [];
const materialTransitTimes = {};

for (const item of masterRaw) {
    const row = item.json;
    const cCode = row["client_code"];
    const sCode = row["supplier_code"];
    const sFull = row["supplier_name_full"];
    const mCode = row["material_code"];
    const transit = row["transit_time_days"];

    if (cCode === clientCode) {
        if (sFull) {
            existingMasterCombos.add(`${cCode}_${normalizeString(sFull)}_${normalizeString(mCode)}`);
            existingSupplierCodes[normalizeString(sFull)] = sCode;
        }
        if (sCode) {
            existingSupplierCodesByCode[String(sCode).trim()] = sFull;
        }
    }

    if (sCode) {
        const sMatch = String(sCode).trim().match(/^S(\d+)$/i);
        if (sMatch) {
            existingSNums.push(parseInt(sMatch[1], 10));
        }
    }

    if (mCode && transit !== null && transit !== undefined) {
        try {
            materialTransitTimes[normalizeString(mCode)] = parseInt(parseFloat(transit), 10);
        } catch (e) {}
    }
}

let currentSCounter = existingSNums.length > 0 ? Math.max(...existingSNums) : 0;

// 5. Extract existing PO Consolidated records
const existingPocCombos = new Set();
const existingPocLineItems = {};
const existingGroupIds = [];

for (const item of pocRaw) {
    const row = item.json;
    const cCode = row["client_code"];
    const gId = row["comms_group_id"];
    const poNum = row["po_number"];
    const lineItem = row["po_line_item"];
    const mCode = row["material_code"];

    if (cCode === clientCode) {
        existingPocCombos.add(`${cCode}_${String(poNum).trim()}_${normalizeString(mCode)}`);
        if (poNum) {
            const poStr = String(poNum).trim();
            if (!existingPocLineItems[poStr]) {
                existingPocLineItems[poStr] = [];
            }
            try {
                existingPocLineItems[poStr].push(parseInt(parseFloat(lineItem), 10));
            } catch (e) {}
        }
    }
    if (gId) {
        const gMatch = String(gId).trim().match(/^G(\d+)$/i);
        if (gMatch) {
            existingGroupIds.push(parseInt(gMatch[1], 10));
        }
    }
}

let maxGroupNum = existingGroupIds.length > 0 ? Math.max(...existingGroupIds) : 0;

// 6. Extract existing Log keys
const existingLogKeys = new Set();
for (const item of logsRaw) {
    const row = item.json;
    const cCode = row["client_code"];
    const poNum = row["po_number"];
    const lineItem = row["po_line_item"];
    if (cCode && poNum && lineItem !== null && lineItem !== undefined) {
        let liStr = "";
        try {
            liStr = String(parseInt(parseFloat(lineItem), 10));
        } catch (e) {
            liStr = String(lineItem).trim();
        }
        existingLogKeys.add(`${cCode}_${String(poNum).trim()}_${liStr}`);
    }
}

// 7. Load Bands Table
const bandsList = [];
for (const item of bandsRaw) {
    const row = item.json;
    const bandLetter = row["Ship-by Window (days)"] || row["band"] || row["Bands mapping"];
    const wMin = row["min"] || row["Min Window"];
    const wMax = row["max"] || row["Max Window"];
    if (bandLetter !== null && bandLetter !== undefined && wMin !== null && wMax !== null) {
        try {
            bandsList.push({
                band: String(bandLetter).trim(),
                min: parseInt(parseFloat(wMin), 10),
                max: parseInt(parseFloat(wMax), 10)
            });
        } catch (e) {}
    }
}

// 8. Scan and Filter incoming ERP PO lines
let parsedLines = [];
for (const item of poLatestRaw) {
    const row = item.json;
    const vendorName = getValueByHeaderVariant(row, 'vendor_name');
    const vendorCode = getValueByHeaderVariant(row, 'vendor_code');
    const poNum = getValueByHeaderVariant(row, 'po_number');
    const itemNo = getValueByHeaderVariant(row, 'item_no');

    if (!vendorName || !poNum || !itemNo) {
        continue;
    }
    const defaultYear = runDate.getFullYear();
    const poDate = parseDate(getValueByHeaderVariant(row, 'po_date'), defaultYear);
    const arrivalDate = parseDate(getValueByHeaderVariant(row, 'arrival_date'), defaultYear);
    const uomRaw = getValueByHeaderVariant(row, 'uom');
    const uomStr = uomRaw !== null && uomRaw !== undefined && String(uomRaw).trim() !== "" ? String(uomRaw).trim() : "kg";

    parsedLines.push({
        vendor_name: String(vendorName).trim(),
        vendor_code: vendorCode ? String(vendorCode).trim() : null,
        po_number: String(poNum).trim(),
        po_date: poDate,
        item_no: String(itemNo).trim(),
        description: getValueByHeaderVariant(row, 'description', ""),
        qty: parseFloat(getValueByHeaderVariant(row, 'qty', 0)),
        price: parseFloat(getValueByHeaderVariant(row, 'price', 0)),
        amount: parseFloat(getValueByHeaderVariant(row, 'amount', 0)),
        terms: getValueByHeaderVariant(row, 'terms', ""),
        arrival_date: arrivalDate,
        shipto: getValueByHeaderVariant(row, 'shipto', ""),
        uom: uomStr
    });
}

// Filter duplicates against existing POC
parsedLines = parsedLines.filter(p => !existingPocCombos.has(`${clientCode}_${p.po_number}_${normalizeString(p.item_no)}`));

// 9. Process Supplier Master Mapping & Ingestion
const newMasterAppends = [];
const tempMasterCombos = new Set(existingMasterCombos);
const filteredParsedLines = [];
const manualReviews = [];
const flaggedVendorsInRun = new Set();

for (const p of parsedLines) {
    const vname = p.vendor_name;
    let vcode = p.vendor_code;
    if (vcode) {
        vcode = String(vcode).trim();
        if (!vcode || vcode === "None" || vcode === "-") {
            vcode = null;
        }
    } else {
        vcode = null;
    }

    const normVname = normalizeString(vname);

    if (flaggedVendorsInRun.has(normVname)) {
        continue;
    }

    let sCode = null;
    // Match A: Name Match
    if (existingSupplierCodes[normVname]) {
        sCode = existingSupplierCodes[normVname];
    } else {
        // Match B: Code Match
        if (vcode && existingSupplierCodesByCode.hasOwnProperty(vcode)) {
            const matchedName = existingSupplierCodesByCode[vcode];
            manualReviews.push({
                candidate_name: vname,
                candidate_code: vcode,
                existing_name_full: matchedName
            });
            flaggedVendorsInRun.add(normVname);
            continue;
        }

        if (vcode) {
            sCode = vcode;
        } else {
            currentSCounter += 1;
            sCode = `S${currentSCounter}`;
        }

        existingSupplierCodes[normVname] = sCode;
        existingSupplierCodesByCode[sCode] = vname;
    }

    p.supplier_code = sCode;
    filteredParsedLines.push(p);

    const mCombo = `${clientCode}_${normVname}_${normalizeString(p.item_no)}`;
    if (!tempMasterCombos.has(mCombo)) {
        tempMasterCombos.add(mCombo);
        const contactInfo = contactsMap[normVname] || { contact_name: '', email: '', phone: '' };

        newMasterAppends.push({
            client_code: clientCode,
            supplier_code: sCode,
            supplier_name_full: vname,
            supplier_name: vname,
            material_code: p.item_no,
            material_name: p.description,
            primary_contact_name: contactInfo.contact_name,
            primary_email: contactInfo.email,
            primary_phone: contactInfo.phone,
            supplier_source_location: p.shipto
        });
    }
}

parsedLines = filteredParsedLines;

// 10. PO Line Sequence counters
const poItemCounters = {};
for (const p of parsedLines) {
    const poStr = p.po_number;
    if (!poItemCounters[poStr]) {
        if (existingPocLineItems[poStr]) {
            poItemCounters[poStr] = Math.max(...existingPocLineItems[poStr]);
        } else {
            poItemCounters[poStr] = 0;
        }
    }
    poItemCounters[poStr] += 1;
    p.po_line_item = poItemCounters[poStr];
}

// 11. Comms Grouping (Gap <= 5 days)
const groupingBuckets = {};
for (const p of parsedLines) {
    const key = `${p.supplier_code}_${p.po_number}`;
    if (!groupingBuckets[key]) {
        groupingBuckets[key] = [];
    }
    groupingBuckets[key].push(p);
}

for (const key in groupingBuckets) {
    const lines = groupingBuckets[key];
    const linesSorted = [...lines].sort((a, b) => {
        const da = a.arrival_date ? a.arrival_date.getTime() : Infinity;
        const db = b.arrival_date ? b.arrival_date.getTime() : Infinity;
        return da - db;
    });

    let currentSubgroup = [];
    for (const line of linesSorted) {
        if (currentSubgroup.length === 0) {
            currentSubgroup.push(line);
        } else {
            const prevLine = currentSubgroup[currentSubgroup.length - 1];
            if (prevLine.arrival_date && line.arrival_date) {
                const gapMs = line.arrival_date.getTime() - prevLine.arrival_date.getTime();
                const gapDays = gapMs / (1000 * 60 * 60 * 24);
                if (gapDays <= 5) {
                    currentSubgroup.push(line);
                } else {
                    maxGroupNum += 1;
                    for (const l of currentSubgroup) {
                        l.comms_group_id = `G${maxGroupNum}`;
                    }
                    currentSubgroup = [line];
                }
            } else {
                maxGroupNum += 1;
                for (const l of currentSubgroup) {
                    l.comms_group_id = `G${maxGroupNum}`;
                }
                currentSubgroup = [line];
            }
        }
    }
    if (currentSubgroup.length > 0) {
        maxGroupNum += 1;
        for (const l of currentSubgroup) {
            l.comms_group_id = `G${maxGroupNum}`;
        }
    }
}

// 12. Map PO Consolidated & Logs Data Lists
const newPocRows = [];
const newLogRows = [];
const tempPocCombos = new Set(existingPocCombos);
const tempLogKeys = new Set(existingLogKeys);

const masterStart = masterRaw.length + 1;
const pocStart = pocRaw.length + 1;
const logsStart = logsRaw.length + 1;

for (let idx = 0; idx < parsedLines.length; idx++) {
    const p = parsedLines[idx];
    const itemNo = p.item_no;
    const sCode = p.supplier_code;
    const commsId = p.comms_group_id;
    const lineItemNum = p.po_line_item;

    const pocCombo = `${clientCode}_${p.po_number}_${normalizeString(itemNo)}`;
    if (!tempPocCombos.has(pocCombo)) {
        tempPocCombos.add(pocCombo);
        const transitDays = materialTransitTimes[normalizeString(itemNo)] !== undefined ? materialTransitTimes[normalizeString(itemNo)] : 3;

        let bandLetter = "G";
        if (p.arrival_date && p.po_date) {
            const shipDate = new Date(p.arrival_date);
            shipDate.setDate(shipDate.getDate() - transitDays);
            const windowMs = shipDate.getTime() - p.po_date.getTime();
            const windowDays = Math.floor(windowMs / (1000 * 60 * 60 * 24));

            for (const band of bandsList) {
                if (windowDays >= band.min && windowDays <= band.max) {
                    bandLetter = band.band;
                    break;
                }
            }
        }

        const rowOffset = pocStart + newPocRows.length + 1;
        newPocRows.push({
            po_line_key: `=B${rowOffset}&"_"&E${rowOffset}&"_"&H${rowOffset}`,
            client_code: clientCode,
            client_company_name: `=iferror(vlookup(B${rowOffset},'Client info'!$A$1:$M$1000,3,False),"-")`,
            comms_group_id: commsId,
            po_number: p.po_number,
            supplier_code: sCode,
            supplier_name: `=iferror(vlookup(F${rowOffset},'${masterTitle}'!$D$1:$F$20000,3,False),"-")`,
            po_line_item: lineItemNum,
            material_code: itemNo,
            material_name: p.description,
            quantity: p.qty,
            unit_of_measure: p.uom,
            issue_date: formatDateStr(p.po_date),
            po_status: 'Open',
            deliver_by_date_delivery_1: formatDateStr(p.arrival_date),
            ship_by_date_delivery_1: `=S${rowOffset}-${transitDays}`,
            number_of_ship_by_days: `=T${rowOffset}-O${rowOffset}`,
            ship_by_band: bandLetter,
            quantity_delivery_1: p.qty,
            last_updated: formatDateTime(runDatetime),
            primary_email: `=vlookup(F${rowOffset},'${masterTitle}'!$D$1:$J$20000,7,False)`
        });
    }

    const logKeyVal = `${clientCode}_${p.po_number}_${lineItemNum}`;
    if (!tempLogKeys.has(logKeyVal)) {
        tempLogKeys.add(logKeyVal);

        let stageStr = "Stage1";
        const transitDays = materialTransitTimes[normalizeString(itemNo)] !== undefined ? materialTransitTimes[normalizeString(itemNo)] : 3;
        if (p.arrival_date && p.po_date) {
            const shipDate = new Date(p.arrival_date);
            shipDate.setDate(shipDate.getDate() - transitDays);
            const totalWindow = (shipDate.getTime() - p.po_date.getTime()) / (1000 * 60 * 60 * 24);
            const passedWindow = (runDate.getTime() - p.po_date.getTime()) / (1000 * 60 * 60 * 24);
            const pctPassed = totalWindow > 0 ? (passedWindow / totalWindow * 100) : (passedWindow > 0 ? 100 : 0);
            if (pctPassed <= 40) {
                stageStr = "Stage1";
            } else if (pctPassed <= 80) {
                stageStr = "Stage2";
            } else {
                stageStr = "Stage3";
            }
        }

        const rowOffset = logsStart + newLogRows.length + 1;
        newLogRows.push({
            po_line_key: `=B${rowOffset}&"_"&E${rowOffset}&"_"&H${rowOffset}`,
            client_code: clientCode,
            client_company_name: `=iferror(vlookup(B${rowOffset},'Client info'!$A$1:$M$1000,3,False),"-")`,
            comms_group_id: commsId,
            po_number: p.po_number,
            supplier_code: sCode,
            supplier_name: `=iferror(vlookup(F${rowOffset},'${masterTitle}'!$D$1:$F$20000,3,False),"-")`,
            po_line_item: lineItemNum,
            material_code: itemNo,
            material_name: `=vlookup(I${rowOffset},'${masterTitle}'!$G$1:$H$20000,2,False)`,
            follow_up_stage: stageStr,
            follow_up_status: 'Stage_Initiated',
            last_action_timestamp: formatDateTime(runDatetime)
        });
    }
}

const finalMasterRows = [];
for (let idx = 0; idx < newMasterAppends.length; idx++) {
    const m = newMasterAppends[idx];
    const rowOffset = masterStart + idx + 1;
    finalMasterRows.push({
        supplier_email_key: `=B${rowOffset}&"_"&D${rowOffset}&"_"&J${rowOffset}`,
        client_code: m.client_code,
        client_company_short_name: `=iferror(vlookup(B${rowOffset},'Client info'!$A$1:$M$1000,3,False),"-")`,
        supplier_code: m.supplier_code,
        supplier_name_full: m.supplier_name_full,
        supplier_name: m.supplier_name,
        material_code: m.material_code,
        material_name: m.material_name,
        primary_contact_names: m.primary_contact_name,
        primary_emails: m.primary_email,
        primary_phones: m.primary_phone,
        working_days: 'Mon,Tue,Wed,Thu,Fri,Sat',
        supplier_source_location: m.supplier_source_location,
        PO_active: 'Y',
        ai_agent_buyer_name: `=vlookup(B${rowOffset},'Client info'!$A$1:$M$4,11,False)`,
        ai_agent_buyer_position: `=vlookup(B${rowOffset},'Client info'!$A$1:$M$4,12,False)`,
        ai_agent_buyer_email: `=vlookup(B${rowOffset},'Client info'!$A$1:$M$4,13,False)`
    });
}

// Return output structured array for downstream n8n nodes
return [
    {
        json: {
            new_master_rows: finalMasterRows,
            new_poc_rows: newPocRows,
            new_log_rows: newLogRows,
            manual_reviews: manualReviews
        }
    }
];
